<?php
require 'config.php';require_login();verify_csrf();$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){try{$s=db()->prepare("INSERT INTO factoring(load_id,factoring_company,submitted_date,gross_amount,fee,reserve_amount,funded_amount,status,reference_no,notes) VALUES(?,?,?,?,?,?,?,?,?,?)");$s->execute([(int)$_POST['load_id'],$_POST['factoring_company'],$_POST['submitted_date'],$_POST['gross_amount'],$_POST['fee'],$_POST['reserve_amount'],$_POST['gross_amount']-$_POST['fee']-$_POST['reserve_amount'],$_POST['status'],$_POST['reference_no'],$_POST['notes']]);db()->prepare("UPDATE loads SET factoring_status=? WHERE id=?")->execute([$_POST['status'],(int)$_POST['load_id']]);flash('success','Factoring record saved.');redirect('factoring.php');}catch(Throwable $e){$error=$e->getMessage();}}
if(isset($_GET['funded'])&&current_user()['role']==='admin'){db()->prepare("UPDATE factoring SET status='Funded',funded_date=CURDATE() WHERE id=?")->execute([(int)$_GET['funded']]);flash('success','Factoring marked funded.');redirect('factoring.php');}
$loads=db()->query("SELECT id,load_no,rate FROM loads ORDER BY id DESC")->fetchAll();$rows=db()->query("SELECT f.*,l.load_no FROM factoring f JOIN loads l ON l.id=f.load_id ORDER BY f.id DESC")->fetchAll();$pageTitle='Factoring';$active='factoring';require 'partials_header.php';?>
<div class="page-head"><div><h1>Factoring management</h1><p>Track submitted loads, fees, reserves and funded amounts.</p></div></div><div class="form-card" style="margin-bottom:20px"><h3>Submit load to factoring company</h3><?php if($error):?><div class="alert error"><?=e($error)?></div><?php endif;?><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><div class="form-grid"><div class="field"><label>Load *</label><select name="load_id"><?php foreach($loads as $l):?><option value="<?=$l['id']?>"><?=e($l['load_no'])?> · <?=money($l['rate'])?></option><?php endforeach;?></select></div><div class="field"><label>Factoring company *</label><input name="factoring_company" required></div><div class="field"><label>Submitted date</label><input type="date" name="submitted_date" required value="<?=date('Y-m-d')?>"></div><div class="field"><label>Gross amount</label><input type="number" step=".01" name="gross_amount" required></div><div class="field"><label>Factoring fee</label><input type="number" step=".01" name="fee" value="0"></div><div class="field"><label>Reserve amount</label><input type="number" step=".01" name="reserve_amount" value="0"></div><div class="field"><label>Status</label><select name="status"><option>Submitted</option><option>Funded</option><option>Reserve Released</option><option>Rejected</option></select></div><div class="field"><label>Reference number</label><input name="reference_no"></div><div class="field full"><label>Notes</label><textarea name="notes"></textarea></div></div><div class="form-actions"><button class="btn primary">Save factoring record</button></div></form></div>
<div class="table-wrap"><table class="table"><thead><tr><th>Load</th><th>Factoring company</th><th>Gross</th><th>Fee</th><th>Reserve</th><th>Net funded</th><th>Status</th><th></th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=e($r['load_no'])?></td><td><?=e($r['factoring_company'])?></td><td><?=money($r['gross_amount'])?></td><td><?=money($r['fee'])?></td><td><?=money($r['reserve_amount'])?></td><td><?=money($r['funded_amount'])?></td><td><?=e($r['status'])?></td><td><?php if($r['status']==='Submitted'):?><a href="?funded=<?=$r['id']?>">Mark funded</a><?php endif;?></td></tr><?php endforeach;?><?php if(!$rows):?><tr><td colspan="8" class="empty">No factoring records yet.</td></tr><?php endif;?></tbody></table></div><?php require 'partials_footer.php';?>